begin;
do $$declare tid uuid:=gen_random_uuid(); aid uuid:=gen_random_uuid(); begin
 insert into auth.users(id,email,raw_app_meta_data) values
 (tid,tid||'@example.invalid',jsonb_build_object('poker_account',true,'poker_username','Test_'||substr(replace(tid::text,'-',''),1,20))),
 (aid,aid||'@example.invalid',jsonb_build_object('poker_account',true,'poker_username','Test_'||substr(replace(aid::text,'-',''),1,20)));
 update public.poker_accounts set approved=true where user_id in(tid,aid);
 perform set_config('test.member',tid::text,true); perform set_config('test.admin',aid::text,true);
 perform set_config('test.owner',(select user_id::text from public.poker_accounts where role='owner'),true);
end;$$;
set local role authenticated;
do $$declare oid text:=current_setting('test.owner');tid text:=current_setting('test.member');aid text:=current_setting('test.admin'); denied boolean;sid uuid:=gen_random_uuid();s jsonb;snap jsonb;op uuid;begin
 perform set_config('request.jwt.claim.sub',oid,true);
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','role','payload',jsonb_build_object('userId',aid,'role','admin')));
 perform set_config('request.jwt.claim.sub',aid,true);
 assert jsonb_array_length(public.poker_snapshot()->'accounts')>=3,'Admin lista integrantes';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','role','payload',jsonb_build_object('userId',tid,'role','organizer')));
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','role','payload',jsonb_build_object('userId',tid,'role','admin')));exception when insufficient_privilege then denied:=true;end;assert denied,'Admin nao concede admin';
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','deactivate','payload',jsonb_build_object('userId',oid,'active',false)));exception when others then denied:=true;end;assert denied,'Principal protegido';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','player','payload',jsonb_build_object('id',aid,'name','João   Clube Teste','active',true)));
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','player','payload',jsonb_build_object('id',tid,'name','  JOAO Clube TESTE  ','active',true)));exception when unique_violation then denied:=true;end;assert denied,'Nome normalizado duplicado rejeitado';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','deactivate','payload',jsonb_build_object('userId',tid,'active',false)));
 perform set_config('request.jwt.claim.sub',tid,true);
 denied:=false;begin perform public.poker_snapshot();exception when insufficient_privilege then denied:=true;end;assert denied,'Conta desativada perde leitura com JWT existente';
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','settings','payload','{}'::jsonb));exception when insufficient_privilege then denied:=true;end;assert denied,'Conta desativada perde escrita';
 perform set_config('request.jwt.claim.sub',aid,true);
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','deactivate','payload',jsonb_build_object('userId',tid,'active',true)));
 snap:=public.poker_snapshot();
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','create','payload',jsonb_build_object('id',sid,'name','Teste de exclusao','ancient','Teste','startedAt','2026-10-27T12:00:00Z','mode','quick','variant','texas','buyin',500,'rebuy',500,'chips',snap->'settings'->'chips','players',jsonb_build_array(aid,tid))));
 select x into s from jsonb_array_elements(public.poker_snapshot()->'sessions') x where x->>'id'=sid::text;
 perform set_config('request.jwt.claim.sub',tid,true);
 op:=gen_random_uuid();
 perform public.poker_command(jsonb_build_object('id',op,'type','deleteSession','sessionId',sid,'expectedRevision',s->'revision','payload',jsonb_build_object('reason','Teste transacional')));
 assert not exists(select 1 from jsonb_array_elements(public.poker_snapshot()->'sessions') x where x->>'id'=sid::text),'Organizador exclui do arquivo';
 perform set_config('request.jwt.claim.sub',aid,true);
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','role','payload',jsonb_build_object('userId',tid,'role','member')));
 perform set_config('request.jwt.claim.sub',oid,true);
 select x into s from jsonb_array_elements(public.poker_snapshot()->'deletedSessions') x where x->>'id'=sid::text;
 assert s is not null,'Exclusao preserva dados';
 assert exists(select 1 from jsonb_array_elements(public.poker_snapshot()->'audit') a where a->>'type'='deleteSession'),'Exclusao auditada';
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','restoreSession','sessionId',sid,'expectedRevision',s->'revision','payload',jsonb_build_object('reason','Restauracao de teste')));
 select x into s from jsonb_array_elements(public.poker_snapshot()->'sessions') x where x->>'id'=sid::text;
 perform set_config('request.jwt.claim.sub',tid,true);
 denied:=false;begin perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','deleteSession','sessionId',sid,'expectedRevision',s->'revision','payload',jsonb_build_object('reason','Tentativa sem permissao')));exception when insufficient_privilege then denied:=true;end;assert denied,'Membro nao exclui';
 perform set_config('request.jwt.claim.sub',oid,true);
 perform public.poker_command(jsonb_build_object('id',gen_random_uuid(),'type','role','payload',jsonb_build_object('userId',aid,'role','organizer')));
 perform set_config('request.jwt.claim.sub',aid,true);
 assert jsonb_array_length(public.poker_snapshot()->'accounts')=0,'Retirada de TcheTche revoga gestao';
end;$$;
rollback;
select 'PASS: TcheTche, principal protegido, nomes normalizados, desativacao, revogacao, exclusao e recuperacao' as resultado;
